python3 -c "import random, shutil, time, os; os.system('osascript -e ' + chr(39) + 'tell application ' + chr(34) + 'Music' + chr(34) + ' to play' + chr(39)); w = ['kill', 'code', 'error', 'loop', 'system', 'terminal', 'coffee', 'data', 'buffer', 'chaos', 'run', 'process', 'dump', 'stack', 'overflow', 'matrix', 'node', 'shell', 'script', 'byte']; img = ['  ██████╗ ██╗   ██╗███╗   ██╗██╗██╗  ██╗  ', '  ██╔══██╗██║   ██║████╗  ██║██║╚██╗██╔╝  ', '  ██████╔╝██║   ██║██╔██╗ ██║██║ ╚███╔╝   ', '  ██╔══██╗██║   ██║██║╚██╗██║██║ ██╔██╗   ', '  ██║  ██║╚██████╔╝██║ ╚████║██║██╔╝ ██╗  ', '  ╚═╝  ╚═╝ ╚═════╝ ╚═╝  ╚═══╝╚═╝╚═╝  ╚═╝  ']; exec('while True:\n try:\n  cols, rows = shutil.get_terminal_size(); print(\"\033[H\033[2J\", end=\"\");\n  for _ in range(rows - 1):\n   line = \" \".join(random.choices(w, k=50))[:cols]; color = f\"\033[38;5;{random.randint(22, 28)}m\"; print(f\"{color}{line.ljust(cols)}\033[0m\")\n  start_row = max(1, (rows - len(img)) // 2);\n  for i, line in enumerate(img):\n   print(f\"\033[{start_row + i};1H\033[1;38;5;82m{line.center(cols)}\033[0m\", end=\"\")\n  time.sleep(0.06)\n except KeyboardInterrupt:\n  pass')"
